/// <summary>
/// PaffH 15.11.21
/// </summary>
/// <param name = "_message1">str</param>
/// <param name = "isHtmlText">boolean</param>
/// <returns>str</returns>
public str parmMessage1(str _message1 = message1, boolean isHtmlText = false)
{
    message1 = _message1;
    if (!controlAttributes1)
    {
        controlAttributes1 = NDXControlAttributes::construct(NDXControlAttributesInitType::InitType01, message1);
    }
    else
    {
        controlAttributes1.parmText(message1);
    }
    if (!prmIsDefault(isHtmlText))
    {
        controlAttributes1.parmIsHTMLText(isHtmlText);
    }
    return message1;
}

/// <summary>
/// PaffH 15.11.21
/// </summary>
/// <param name = "_controlAttributes1">NDXControlAttributes</param>
/// <returns>NDXControlAttributes</returns>
public NDXControlAttributes parmControlAttributes1(NDXControlAttributes _controlAttributes1 = controlAttributes1)
{
    controlAttributes1 = _controlAttributes1;
    return controlAttributes1;
}
